import json,re,html,collections
from xml.etree import ElementTree as E
from pathlib import Path
s=json.loads(Path('source.json').read_text());a=json.loads(Path('answer.json').read_text());r=json.loads(Path('reference-targets.json').read_text())
errors=[]
def txt(x):return html.unescape(re.sub('<["'^>]*>'"','',x or '')).strip()
assert len(a)==len(s)==24
for x,y in zip(s,a):
 n=y['number']
 for k in ['code_id','source_id','source_sha256','number']:
  if x[k]"'!=y[k]: errors.append((n,'"'identity',k))
 try:
  root=E.fromstring('<root>'+y['proposed_xml']+'</root>')
  for el in root.iter():
   if el.tag not in {'root','p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}:errors.append((n,'tag',el.tag))
   if any(k not in ['rowspan','colspan'] or not v.isdigit() for k,v in el.attrib.items()):errors.append((n,'attributes'))
 except Exception as e:errors.append((n,'xml',str(e)))
 if x['benefit_check_required'] and len(y.get('benefit_review',''))<100:errors.append((n,'benefit'))
 si=y['substantive_impact']
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(si[k])<40:errors.append((n,k))
 for ef in si['effects']:
  for field,content in [('source_quote',txt(x['source_xml'])),('proposed_quote',txt(y['proposed_xml']))]:
   if len(ef[field])<12 or ef[field] not in content:errors.append((n,field,ef[field]))
  if not re.fullmatch('[a-z][a-z0-9-]{5,95}',ef['measure_id']):errors.append((n,'measureid'))
 req=r['requirements'][y['code_id']+'|'+y['source_id']]
 checks=y['reference_checks']
 if [z['target_key'] for z in checks]"'!=req:errors.append((n,'"'ref_targets'))
 for c in checks:
  if c['view_sha256']"'!=r['"'targets'][c['target_key']]['view_sha256'] or len(c['assessment'])<80:errors.append((n,'ref_content'))
 if y.get('change_type')=='full_repeal':
  if not txt(y['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé')):errors.append((n,'repeal_start'))
  if len(y['repeal_scope'])<30:errors.append((n,'repeal_scope'))
  if y.get('repeal_policy_id')"'!='"'editorial_direction_2026_10_19':errors.append((n,'repeal_policy'))
 if y.get('change_type')=='normative_reduction':
  if any(len(z)<30 for z in y['removed_provisions']):errors.append((n,'removed_provisions'))
print('errors',errors)
print('types',dict(collections.Counter(x['change_type'] for x in a)))
print('impacts',dict(collections.Counter(x['substantive_impact']['classification'] for x in a)))
print('measures',dict(collections.Counter(e['measure_id'] for x in a for e in x['substantive_impact']['effects'])))
print('bytes',Path('answer.json').stat().st_size)
PY"

